    @if($images->isNotEmpty())<div class="fixed inset-0 z-[100] hidden items-center justify-center bg-black/90 p-4" id="room-lightbox" role="dialog" aria-modal="true"><button class="absolute right-5 top-5 flex h-12 w-12 items-center justify-center rounded-full bg-white/10 text-white hover:bg-white hover:text-black" id="room-lightbox-close" type="button" aria-label="Galeriyi kapat"><span class="material-symbols-outlined">close</span></button><button class="absolute left-4 top-1/2 flex h-12 w-12 -translate-y-1/2 items-center justify-center rounded-full bg-white/10 text-white hover:bg-white hover:text-black" id="room-lightbox-prev" type="button" aria-label="Önceki görsel"><span class="material-symbols-outlined">arrow_back</span></button><img class="max-h-[85vh] max-w-[90vw] object-contain" id="room-lightbox-image" src="" alt="{{ $roomType->translatedName() }}"><button class="absolute right-4 top-1/2 flex h-12 w-12 -translate-y-1/2 items-center justify-center rounded-full bg-white/10 text-white hover:bg-white hover:text-black" id="room-lightbox-next" type="button" aria-label="Sonraki görsel"><span class="material-symbols-outlined">arrow_forward</span></button><span class="absolute bottom-5 left-1/2 -translate-x-1/2 text-sm text-white" id="room-lightbox-counter"></span></div>@endif

    @push('scripts')<script>document.addEventListener('DOMContentLoaded', function () { const images = @json($images->map(fn ($image) => $image->imageUrl())->values()); const modal = document.getElementById('room-lightbox'); if (!modal || !images.length) return; const image = document.getElementById('room-lightbox-image'); const counter = document.getElementById('room-lightbox-counter'); let index = 0; const show = () => { image.src = images[index]; counter.textContent = `${index + 1} / ${images.length}`; }; document.querySelectorAll('.room-gallery-image').forEach(button => button.addEventListener('click', () => { index = Number(button.dataset.index); show(); modal.classList.remove('hidden'); modal.classList.add('flex'); document.body.style.overflow = 'hidden'; })); const close = () => { modal.classList.add('hidden'); modal.classList.remove('flex'); document.body.style.overflow = ''; }; document.getElementById('room-lightbox-close').addEventListener('click', close); document.getElementById('room-lightbox-prev').addEventListener('click', () => { index = (index - 1 + images.length) % images.length; show(); }); document.getElementById('room-lightbox-next').addEventListener('click', () => { index = (index + 1) % images.length; show(); }); modal.addEventListener('click', event => { if (event.target === modal) close(); }); document.addEventListener('keydown', event => { if (modal.classList.contains('hidden')) return; if (event.key === 'Escape') close(); if (event.key === 'ArrowLeft') document.getElementById('room-lightbox-prev').click(); if (event.key === 'ArrowRight') document.getElementById('room-lightbox-next').click(); }); });</script>@endpush
